use humantime::{parse_duration, DurationError};

#[test]
fn nanosecond_carry_into_seconds_overflows_cleanly() {
    assert_eq!(
        parse_duration(&format!("{}s1000ms", u64::MAX)),
        Err(DurationError::NumberOverflow)
    );
    assert_eq!(
        parse_duration(&format!("{}s 999999999ns 1ns", u64::MAX)),
        Err(DurationError::NumberOverflow)
    );
}

#[test]
fn nanosecond_carry_still_adds_up() {
    assert_eq!(
        parse_duration("1s 999999999ns 1ns"),
        Ok(std::time::Duration::from_secs(2))
    );
}

use bstr::ByteSlice;

#[test]
fn debug_escapes_all_control_characters_as_hex() {
    assert_eq!(
        format!("{:?}", b"\x01\x19\x1a\x1b\x1c\x1d\x1e\x1f\x7f".as_bstr()),
        r#""\x01\x19\x1a\x1b\x1c\x1d\x1e\x1f\x7f""#
    );
    assert_eq!(format!("{:?}", b"a\tb\n".as_bstr()), r#""a\tb\n""#);
}
